# Classify a detected radio signal by band (catalog-level signatures only)
def classify(freq_mhz):
    if 2400 <= freq_mhz <= 2483:
        return "2.4 GHz band: likely control/video link (shared with Wi-Fi)"
    if 5725 <= freq_mhz <= 5875:
        return "5.8 GHz band: likely video link"
    if 902 <= freq_mhz <= 928:
        return "900 MHz band: possible long-range control link"
    return "Outside common drone bands: not classified as a drone link"
for f in [2437, 5805, 915, 1800]:
    print(str(f) + " MHz -> " + classify(f))

# Angular size estimate: how big a drone looks at a given distance
import math
def angular_size_deg(size_m, distance_m):
    return math.degrees(2 * math.atan(size_m / (2 * distance_m)))
for dist in [50, 100, 300]:
    print("0.5 m drone at " + str(dist) + " m spans " + format(angular_size_deg(0.5, dist), ".3f") + " degrees")
print("Small angular size at distance is why classification degrades with range")

# Point-in-polygon geofence check (ray casting, textbook algorithm)
def inside(point, polygon):
    x, y = point
    hit = False
    n = len(polygon)
    for i in range(n):
        x1, y1 = polygon[i]
        x2, y2 = polygon[(i + 1) % n]
        if (y1 > y) != (y2 > y):
            xi = (x2 - x1) * (y - y1) / (y2 - y1) + x1
            if x < xi:
                hit = not hit
    return hit
zone = [(0, 0), (0, 10), (10, 10), (10, 0)]
for p in [(5, 5), (15, 5), (0, 5)]:
    print("Point " + str(p) + " inside restricted zone: " + str(inside(p, zone)))

