# Airport proximity check (illustrative example, distances in km)
def near_airport(dist_km):
    if dist_km < 5:
        return "INSIDE typical controlled zone: authorization required; report any sighting immediately"
    if dist_km < 10:
        return "NEAR airport: check authorization rules before flying; report sightings promptly"
    return "Outside immediate airport zone: normal airspace rules still apply"
for d in [2, 7, 20]:
    print("Distance " + str(d) + " km from airport -> " + near_airport(d))

